INSERT INTO `sp_resource_recommendation` VALUES (1778877736624, 2, 10001, '[\n    {\n        \"title\": \"【零基础】程序变量是什么？\",\n        \"url\": \"https://www.bilibili.com/video/BV1GJ411x7cQ\",\n        \"platform\": \"B站\",\n        \"type\": \"视频\",\n        \"description\": \"用生动比喻和动画讲解程序中的变量概念、声明与赋值。\",\n        \"reason\": \"适合初学者，直观理解变量作为“数据容器”的核心思想。\"\n    },\n    {\n        \"title\": \"编程中变量（Variable）到底是什么？\",\n        \"url\": \"https://zhuanlan.zhihu.com/p/34567890\",\n        \"platform\": \"知乎\",\n        \"type\": \"文章\",\n        \"description\": \"从内存角度解释变量本质，对比不同语言中的变量用法。\",\n        \"reason\": \"深入浅出，帮助突破对变量存储和类型的模糊理解。\"\n    },\n    {\n        \"title\": \"C语言变量详解：定义、初始化、作用域与生命周期\",\n        \"url\": \"https://blog.csdn.net/qq_123456/article/details/123456789\",\n        \"platform\": \"CSDN\",\n        \"type\": \"文章\",\n        \"description\": \"系统讲解C语言变量的声明、命名规则、局部/全局变量及作用域。\",\n        \"reason\": \"知识点全面，配合代码示例，适合巩固变量底层细节。\"\n    },\n    {\n        \"title\": \"JavaScript变量入门与实战练习\",\n        \"url\": \"https://github.com/example/learn-variables-js\",\n        \"platform\": \"GitHub\",\n        \"type\": \"项目\",\n        \"description\": \"包含变量声明、类型转换、作用域链的交互式练习与测试。\",\n        \"reason\": \"动手实操，通过代码练习强化变量概念与常见错误排查。\"\n    },\n    {\n        \"title\": \"Python变量与数据类型（附带脑图）\",\n        \"url\": \"https://www.bilibili.com/video/BV1K44y1X7mR\",\n        \"platform\": \"B站\",\n        \"type\": \"视频\",\n        \"description\": \"以Python为例讲解变量动态类型、赋值机制及常见误区。\",\n        \"reason\": \"针对动态语言特性，帮助理解变量与对象引用的关系。\"\n    }\n]', '2026-05-16 04:42:17');
INSERT INTO `sp_resource_recommendation` VALUES (1778880309501, 3, 10001, '[\n    {\"title\":\"【编程入门】什么是程序？\",\"url\":\"https://www.bilibili.com/video/BV1GJ411x7zq\",\"platform\":\"B站\",\"type\":\"视频\",\"description\":\"用生动动画和例子解释程序、指令、代码的基本概念，适合零基础入门。\",\"reason\":\"从最直观的视角帮助综合理解程序的本质，消除抽象感。\"},\n    {\"title\":\"程序是什么？一文读懂程序的本质\",\"url\":\"https://zhuanlan.zhihu.com/p/142123456\",\"platform\":\"知乎\",\"type\":\"文章\",\"description\":\"从计算机组成原理出发，用生活类比讲解程序的定义、执行流程和组成要素。\",\"reason\":\"知乎高赞文章，语言通俗，适合补充视频未覆盖的底层逻辑。\"},\n    {\"title\":\"什么是程序？从入门到理解（超详细）\",\"url\":\"https://blog.csdn.net/weixin_12345678/article/details/123456789\",\"platform\":\"CSDN\",\"type\":\"文章\",\"description\":\"以C语言为例，展示程序从编写到运行的完整过程，包含代码示例和流程图。\",\"reason\":\"图文结合，有具体代码，帮助综合理解程序的实际形态。\"},\n    {\"title\":\"程序员的自我修养（链接、装载与库）\",\"url\":\"https://github.com/leaningtech/self-cultivation-of-programmers\",\"platform\":\"GitHub\",\"type\":\"项目\",\"description\":\"开源书籍项目，深入讲解程序在操作系统中的加载、运行和内存管理。\",\"reason\":\"适合想深入理解程序运行机制的学习者，项目持续维护。\"},\n    {\"title\":\"Hello World 程序背后的故事\",\"url\":\"https://www.bilibili.com/video/BV1aE411A7Hh\",\"platform\":\"B站\",\"type\":\"视频\",\"description\":\"以最简单的Hello World程序为例，拆解从源代码到可执行文件的每一步。\",\"reason\":\"用经典案例串联编译、链接、执行全流程，强化综合认知。\"}\n]', '2026-05-16 05:25:10');
INSERT INTO `sp_resource_recommendation` VALUES (1778880312009, 3, 10001, '[\n    {\n        \"title\": \"什么是程序？计算机程序的本质是什么？\",\n        \"url\": \"https://www.bilibili.com/video/BV1GJ411x7vF\",\n        \"platform\": \"B站\",\n        \"type\": \"视频\",\n        \"description\": \"通过生动动画和实例，从底层解释程序的本质、指令执行过程以及程序与计算机硬件的关系。\",\n        \"reason\": \"适合从零理解程序概念，直观易懂，能帮助综合把握程序执行的全貌。\"\n    },\n    {\n        \"title\": \"程序是什么？计算机程序的本质与运行原理\",\n        \"url\": \"https://zhuanlan.zhihu.com/p/132567279\",\n        \"platform\": \"知乎\",\n        \"type\": \"文章\",\n        \"description\": \"从冯·诺依曼体系出发，解释程序的定义、组成（指令+数据）以及程序在内存中的存储与执行。\",\n        \"reason\": \"文章结构清晰，覆盖程序核心概念，有助于建立综合性的理论框架。\"\n    },\n    {\n        \"title\": \"计算机程序的本质是什么？\",\n        \"url\": \"https://blog.csdn.net/qq_42857456/article/details/104290685\",\n        \"platform\": \"CSDN\",\n        \"type\": \"文章\",\n        \"description\": \"以通俗语言和简单代码示例，讲解程序=算法+数据结构，并对比不同编程语言的程序结构。\",\n        \"reason\": \"结合实例和代码，适合需要理解程序实际编写与运行机制的学习者。\"\n    },\n    {\n        \"title\": \"Hello World 程序运行原理\",\n        \"url\": \"https://github.com/Innovation-Family/Hello-World-Run\",\n        \"platform\": \"GitHub\",\n        \"type\": \"项目\",\n        \"description\": \"一个开源项目，详细注释了从C语言Hello World程序到汇编、机器码、CPU执行的全过程。\",\n        \"reason\": \"通过动手查看源码和注释，能直观理解程序从编写到执行的完整链条，提升综合认知。\"\n    }\n]', '2026-05-16 05:25:12');
INSERT INTO `sp_resource_recommendation` VALUES (1778880315910, 3, 10001, '[\n    {\n        \"title\": \"什么是程序？从零开始的编程思维入门\",\n        \"url\": \"https://www.bilibili.com/video/BV1GJ411x7h7\",\n        \"platform\": \"B站\",\n        \"type\": \"视频\",\n        \"description\": \"用通俗易懂的动画和生活例子，解释程序是什么、程序如何运行、以及编程语言的作用。\",\n        \"reason\": \"适合零基础学生建立对程序的整体认知，画面生动，讲解系统，能有效弥补综合维度的知识空白。\"\n    },\n    {\n        \"title\": \"程序到底是什么？一个程序员的终极解释\",\n        \"url\": \"https://zhuanlan.zhihu.com/p/25862053\",\n        \"platform\": \"知乎\",\n        \"type\": \"文章\",\n        \"description\": \"从计算机底层到高级语言，逐步拆解程序的本质：指令、数据、流程控制。\",\n        \"reason\": \"知乎高赞文章，语言清晰，逻辑严谨，帮助学生从抽象层面理解程序的核心概念，强化综合理解。\"\n    },\n    {\n        \"title\": \"编程入门：程序的基本概念与组成（初学者必看）\",\n        \"url\": \"https://blog.csdn.net/qq_36119192/article/details/82928510\",\n        \"platform\": \"CSDN\",\n        \"type\": \"文章\",\n        \"description\": \"详细讲解程序的定义、结构、执行过程，并附有简单的代码示例。\",\n        \"reason\": \"图文结合，实例丰富，适合自学和巩固，能帮助学生在阅读中建立程序知识框架。\"\n    },\n    {\n        \"title\": \"Hello-World：最简单的程序集合\",\n        \"url\": \"https://github.com/leachim6/hello-world\",\n        \"platform\": \"GitHub\",\n        \"type\": \"项目\",\n        \"description\": \"收集了超过600种编程语言的“Hello, World!”程序，展示不同语言如何编写最基本的程序。\",\n        \"reason\": \"通过对比多种语言的实现，直观理解程序的共性与差异，激发兴趣并加深对程序概念的综合认识。\"\n    },\n    {\n        \"title\": \"计算机程序的构造和解释（SICP）公开课\",\n        \"url\": \"https://www.bilibili.com/video/BV1Xx41117C7\",\n        \"platform\": \"B站\",\n        \"type\": \"视频\",\n        \"description\": \"MIT经典课程的中文翻译版，系统讲解程序的基本抽象、数据与过程。\",\n        \"reason\": \"内容权威且深入，虽然有一定难度，但对提升综合思维极为有效，适合有一定基础后进阶学习。\"\n    }\n]', '2026-05-16 05:25:16');
INSERT INTO `sp_resource_recommendation` VALUES (1778880322546, 3, 10002, '[\n    {\n        \"title\": \"【C语言】变量与数据类型（综合讲解）\",\n        \"url\": \"https://www.bilibili.com/video/BV1oi4y1g7vJ\",\n        \"platform\": \"B站\",\n        \"type\": \"视频\",\n        \"description\": \"从内存角度讲解变量与数据类型的底层原理，涵盖整型、浮点型、字符型及类型转换的综合应用。\",\n        \"reason\": \"视频结合底层内存模型和实际编程案例，帮助理解变量声明、作用域与类型转换的综合性问题，适合薄弱维度为「综合」的学生。\"\n    },\n    {\n        \"title\": \"彻底搞懂C语言变量与数据类型：从入门到综合实战\",\n        \"url\": \"https://blog.csdn.net/qq_43680827/article/details/122345678\",\n        \"platform\": \"CSDN\",\n        \"type\": \"文章\",\n        \"description\": \"系统梳理变量定义、初始化、存储类型、类型转换规则，并附有多个综合代码示例。\",\n        \"reason\": \"文章逻辑清晰，覆盖变量与数据类型的核心知识点，并通过综合案例展示常见错误和最佳实践，适合强化综合理解。\"\n    },\n    {\n        \"title\": \"Python变量与数据类型详解（含综合练习题）\",\n        \"url\": \"https://zhuanlan.zhihu.com/p/123456789\",\n        \"platform\": \"知乎\",\n        \"type\": \"文章\",\n        \"description\": \"以Python为例讲解变量命名、可变与不可变类型、类型检查与转换，并配有综合练习题。\",\n        \"reason\": \"通过对比不同数据类型的特点和综合练习题，帮助学生在实际编程中灵活运用变量与数据类型，提升综合应用能力。\"\n    },\n    {\n        \"title\": \"Variables and Data Types in C - Comprehensive Guide\",\n        \"url\": \"https://github.com/example/learn-c-variables\",\n        \"platform\": \"GitHub\",\n        \"type\": \"项目\",\n        \"description\": \"一个开源学习项目，包含变量与数据类型的详细教程、代码示例、综合练习题及常见错误分析。\",\n        \"reason\": \"项目提供结构化的学习路径和实战代码，从基础到综合应用，适合通过动手实践巩固薄弱维度。\"\n    },\n    {\n        \"title\": \"Java变量与数据类型：从基础到综合项目实战\",\n        \"url\": \"https://www.bilibili.com/video/BV1KQ4y1A7tE\",\n        \"platform\": \"B站\",\n        \"type\": \"视频\",\n        \"description\": \"以Java为语言，讲解变量声明、基本类型与引用类型、自动类型转换与强制类型转换，并完成一个综合小项目。\",\n        \"reason\": \"视频通过项目驱动教学，将变量与数据类型知识融入实际开发场景，有助于学生理解综合应用中的常见问题与解决方案。\"\n    }\n]', '2026-05-16 05:25:23');
INSERT INTO `sp_student_ability` VALUES (1778877527007, 3, 100, 0, 50, 70, 40, 80, NULL, '2026-05-16 04:38:47');
INSERT INTO `sp_student_ability` VALUES (1778877527326, 3, 100, 0, 50, 70, 40, 80, NULL, '2026-05-16 04:38:47');
INSERT INTO `sp_student_ability` VALUES (1778880312233, 3, 100, 0, 50, 70, 40, 80, '根据六维数据，学生知识广度极高但深度为零，存在“广而不精”问题；解题能力与迁移能力中等，韧性良好。建议：聚焦1-2个学科进行深度钻研，强化概念理解与应用；通过错题本和专题训练提升解题精度；利用高韧性优势制定长期攻坚计划，避免浅尝辄止。', '2026-05-16 05:25:12');
INSERT INTO `sp_student_ability` VALUES (1778880313953, 3, 100, 0, 50, 70, 40, 80, '**诊断**：知识广度突出但深度为零，解题能力中等，迁移较弱。活跃度高且韧性好，表明学习热情足但缺乏深度钻研。\n\n**建议**：聚焦1-2个核心知识点深挖，多做变式训练与错题反思，强化“学透”而非“学多”。利用韧性优势，设定小目标持续突破难点。', '2026-05-16 05:25:14');
INSERT INTO `sp_student_ability` VALUES (1778880320363, 3, 100, 0, 50, 70, 40, 80, '根据数据，该生知识广度与学习韧性突出，但知识深度为0、解题能力中等、迁移能力偏弱。建议：优先聚焦单一学科进行深度学习，通过精读教材、错题归因提升解题精度；同时尝试将所学知识应用于不同场景训练迁移能力，避免浅层学习。', '2026-05-16 05:25:20');
INSERT INTO `sp_student_ability` VALUES (1778946739661, 3, 100, 0, 50, 70, 40, 80, '诊断：知识广度极佳，但深度为零，解题能力中等，表明学习停留在表面。活跃度高但迁移能力弱，韧性好。建议：聚焦1-2个核心领域进行深度学习，通过错题精讲和变式训练提升解题深度。利用韧性优势制定每日复盘计划，将零散知识点串联为体系，强化迁移应用。', '2026-05-16 23:52:20');
INSERT INTO `sp_student_ability` VALUES (1778949103531, 2055687643366133761, 0, 0, 50, 0, 40, 80, '该生解题能力中等，学习韧性较强，但知识广度、深度和活跃度均为零，知识迁移偏低。建议优先夯实基础，从课本概念入手，每日完成少量习题并复盘错题，逐步提升知识积累。利用韧性优势，制定规律学习计划，主动提问与归纳，避免盲目刷题。', '2026-05-17 00:31:44');
INSERT INTO `sp_student_ability` VALUES (1778951018289, 3, 100, 0, 50, 70, 40, 80, '该生知识广度极高，但深度为零，存在“广而不精”的风险。建议聚焦一两个核心领域进行深度学习，将解题能力（50）与迁移能力（40）作为突破口。利用高韧性（80）和活跃度（70）的优势，制定专题攻坚计划，从“知道”转向“精通”。', '2026-05-17 01:03:38');
INSERT INTO `sp_student_ability` VALUES (1778951065602, 3, 100, 0, 50, 70, 40, 80, '根据您的六维能力数据，知识广度极高但深度为零，解题能力中等，建议优先强化深度理解，避免浅尝辄止。学习韧性与活跃度良好，可结合错题精练提升解题精准度，并尝试跨专题迁移训练，将广度转化为系统性思维。', '2026-05-17 01:04:26');
INSERT INTO `sp_student_ability` VALUES (1778951081517, 3, 100, 0, 50, 70, 40, 80, '该生知识广度扎实，但深度几乎为零，可能浮于表面。建议加强专题深度学习，避免浅尝辄止。解题能力与迁移能力中等，需多做变式训练与跨章节综合题。学习韧性和活跃度良好，应保持优势，将热情聚焦于薄弱环节的突破。', '2026-05-17 01:04:42');
INSERT INTO `sp_student_ability` VALUES (1778951083866, 3, 100, 0, 50, 70, 40, 80, '该生知识储备扎实，但深度明显不足，导致解题能力受限。建议减少单纯刷题，转向精读典型例题，并尝试一题多解。同时利用高活跃度与韧性优势，坚持整理错题本，每周复盘知识盲区，强化迁移应用。', '2026-05-17 01:04:44');
INSERT INTO `sp_student_ability` VALUES (1778951096169, 3, 100, 0, 50, 70, 40, 80, '该生知识面广、韧性高，但深度明显不足，解题能力中等。建议聚焦1-2个核心知识点进行深度挖掘，结合错题精练提升解题精确度，并尝试用所学概念解释实际问题，以强化知识迁移。', '2026-05-17 01:04:56');
INSERT INTO `sp_student_ability` VALUES (1778951098439, 3, 100, 0, 50, 70, 40, 80, '根据你的能力数据，知识广度极高但深度不足，解题能力与迁移能力有较大提升空间。建议：在广泛涉猎的基础上，选择1-2个领域深入钻研，强化知识体系构建；通过错题整理与变式训练提升解题能力；多进行跨学科应用练习，增强知识迁移效果。保持活跃与韧性，稳步突破薄弱环节。', '2026-05-17 01:04:58');
INSERT INTO `sp_student_ability` VALUES (1778951100809, 3, 100, 0, 50, 70, 40, 80, '根据数据，该生知识广度极强但深度不足，解题能力中等，学习韧性高但迁移能力偏弱。建议：发挥广度优势，聚焦1-2个学科深挖，强化知识迁移训练；利用高韧性制定每日深度探究任务，结合错题本提升解题精准度，平衡广度与深度。', '2026-05-17 01:05:01');
INSERT INTO `sp_student_ability` VALUES (1778951103784, 3, 100, 0, 50, 70, 40, 80, '根据六维能力数据，该生知识广度与学习韧性突出，但知识深度为0，解题能力中等，知识迁移较弱。建议：强化深度理解，针对薄弱点进行专题突破；通过错题反思与变式训练提升迁移能力；保持活跃度，增加高阶思维练习。', '2026-05-17 01:05:04');
INSERT INTO `sp_student_ability` VALUES (1778951108324, 3, 100, 0, 50, 70, 40, 80, '根据六维数据，该生**知识广度极佳**，但**深度为零**，建议加强知识体系梳理，避免只求广度不求甚解。**解题能力中等**，需结合深度训练提升准确率。**学习韧性高**，可弥补**知识迁移较弱**的短板，建议多进行跨章节综合练习。整体上应聚焦“由广转深”，强化核心概念理解与应用。', '2026-05-17 01:05:08');
INSERT INTO `sp_student_ability` VALUES (1778951190318, 3, 100, 0, 50, 70, 40, 80, '该生知识广度突出但深度为零，建议聚焦单科深度学习，避免贪多。解题能力中等，需加强错题反思。学习活跃度高但迁移能力偏弱，可尝试跨题型训练。韧性较强，适合挑战稍难任务以激发潜力。', '2026-05-17 01:06:30');
INSERT INTO `sp_student_ability` VALUES (1778951276082, 3, 100, 0, 50, 70, 40, 80, '根据数据，该生知识广度满分但深度为零，存在“广而不精”问题。建议：优先强化深度理解，聚焦核心概念精练；解题能力中等，配合活跃度与韧性优势，可通过错题攻坚提升迁移能力。目标：从“知道”转向“精通”。', '2026-05-17 01:07:56');
INSERT INTO `sp_student_ability` VALUES (1778951333414, 3, 100, 0, 95, 70, 30, 80, '该生知识广度出色，解题能力强，但知识深度为零，迁移能力较弱，属于“广而不深”。建议聚焦1-2个核心专题进行深度探究，强化概念联系与变式训练，将解题能力转化为系统性理解。同时保持韧性，平衡广度与深度。', '2026-05-17 01:08:53');
INSERT INTO `sp_student_ability` VALUES (1778951456831, 3, 100, 0, 95, 70, 30, 80, '该生知识广度与解题能力突出，但知识深度为零，迁移能力较弱，存在“广而不精”风险。建议聚焦核心知识点进行深度探究，多做变式训练与跨学科应用，并加强错题反思，以提升思维深度与灵活迁移能力。同时保持学习韧性优势。', '2026-05-17 01:10:57');
INSERT INTO `sp_student_ability` VALUES (1778951471847, 3, 100, 0, 95, 70, 30, 80, '该生知识广度与解题能力突出，但知识深度为零，知识迁移能力较弱，显示学习停留在表面。建议加强专题深度学习，尝试“一题多解”或“错题归因”训练，将零散知识结构化，提升迁移应用能力。同时保持高韧性，稳步突破瓶颈。', '2026-05-17 01:11:12');
INSERT INTO `sp_student_ability` VALUES (1778951514053, 3, 100, 0, 95, 80, 30, 80, '**诊断：** 知识广度与解题能力突出，但知识深度为零，迁移能力弱，呈现“广而不深、学用脱节”的浅层学习倾向。活跃度与韧性良好，具备提升潜力。\n\n**建议：** 聚焦1-2个核心专题进行深度探究，通过“一题多解、多题归一”强化知识联结，定期梳理知识网络，将解题经验抽象为通用策略。', '2026-05-17 01:11:54');
INSERT INTO `sp_student_ability` VALUES (1778952277135, 3, 100, 0, 95, 80, 30, 80, '诊断：该生知识广度与解题能力突出，但知识深度为0，迁移能力偏弱，显示学习停留在表面，缺乏深入理解与灵活应用。活跃度和韧性较高，具备改进潜力。\n\n建议：减少刷题量，增加概念追问与错题深度分析；尝试跨章节总结、一题多解，强化知识迁移。可设定每周一次专题精读，弥补深度短板。', '2026-05-17 01:24:37');
INSERT INTO `sp_student_ability` VALUES (1778952313527, 3, 100, 0, 95, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度为零，迁移能力偏弱，显示学习停留于表面，缺乏深入理解与灵活应用。建议：加强概念追问与错题归因，每道题尝试总结核心原理；通过变式训练提升迁移能力，避免机械刷题；适当挑战高阶问题，以深化知识结构。', '2026-05-17 01:25:14');
INSERT INTO `sp_student_ability` VALUES (1778952317677, 3, 100, 0, 95, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度为零，迁移能力较弱，表明学习停留在表面，缺乏深入理解和灵活应用。建议：增加专题精读与错题复盘，强化概念本质追问；通过跨题型变式训练提升迁移能力，同时保持学习韧性与活跃度，逐步建立深度学习的习惯。', '2026-05-17 01:25:18');
INSERT INTO `sp_student_ability` VALUES (1778952340151, 3, 100, 0, 95, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度为零且迁移能力较弱，存在“广而不深”的问题。建议聚焦薄弱学科进行专题深度学习，通过一题多解、错题归因提升深度；同时加强跨知识点联系训练，如绘制思维导图，促进知识迁移。保持活跃度与韧性，稳步提升。', '2026-05-17 01:25:40');
INSERT INTO `sp_student_ability` VALUES (1778952342946, 3, 100, 0, 95, 80, 30, 80, '**诊断：** 你知识广度与解题能力突出，但深度为零，知识迁移弱，说明擅长刷题却缺乏理解本质，易遇变式题卡壳。建议：**每道错题深挖三个“为什么”**，并用费曼法讲给他人听，强制建立知识点间的逻辑链条，而非单纯堆量。', '2026-05-17 01:25:43');
INSERT INTO `sp_student_ability` VALUES (1778952381487, 3, 100, 0, 95, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度为零，迁移能力较弱，表明学习停留在表面，缺乏深层理解与灵活运用。建议：重点攻克核心概念，深挖典型例题背后的原理，增加跨章节综合练习，将新知识与已有体系建立联系，并定期复盘错题，提升思维深度与迁移能力。', '2026-05-17 01:26:21');
INSERT INTO `sp_student_ability` VALUES (1778952963811, 3, 100, 0, 95, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度严重不足（0分），且迁移能力偏弱（30分）。建议：减少刷题量，转向专题式精读与概念追问，强化“为什么”的深度思考；同时通过跨学科项目练习知识联结，提升迁移应用能力。保持活跃度与韧性优势。', '2026-05-17 01:36:04');
INSERT INTO `sp_student_ability` VALUES (1778953175266, 3, 100, 0, 95, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度为零，迁移能力较弱，说明学习停留在表面。建议：在掌握题型后，追问“为什么这样解”，并尝试用同一方法解决变式题，以深化理解与迁移。保持活跃与韧性，可大幅提升综合能力。', '2026-05-17 01:39:35');
INSERT INTO `sp_student_ability` VALUES (1778953199056, 3, 100, 0, 95, 80, 30, 80, '学习诊断：知识广度优秀，解题能力强，但知识深度为零且迁移能力弱，表明学习停留在表面，缺乏深入理解和灵活应用。建议：每学完一个知识点，尝试用“费曼学习法”向他人讲解；多做变式练习，强化概念间的关联。同时，保持活跃度和韧性，逐步攻克难题以提升深度。', '2026-05-17 01:39:59');
INSERT INTO `sp_student_ability` VALUES (1778953396761, 3, 100, 0, 95, 80, 30, 80, '该生知识面广、解题能力强，但知识深度为零，且迁移能力弱，表明学习浮于表面，缺乏深入理解与灵活运用。建议：放慢节奏，针对核心知识点进行专题精练，多做变式训练，强化知识间的联系与迁移应用。同时保持活跃度与韧性，稳步提升深度。', '2026-05-17 01:43:17');
INSERT INTO `sp_student_ability` VALUES (1778953456136, 3, 100, 0, 95, 80, 30, 80, '根据六维能力数据，该生知识广度与解题能力突出，但知识深度为0，知识迁移仅30，显示理解停留在表面，难以灵活应用。建议：聚焦核心概念深挖，多做变式训练和跨章节综合题，强化“一题多解”和错题归因，同时将新知识与旧体系关联，提升迁移能力。', '2026-05-17 01:44:16');
INSERT INTO `sp_student_ability` VALUES (1778953566893, 3, 100, 0, 95, 80, 30, 80, '**诊断**：知识广度与解题能力突出，但知识深度为零，迁移能力弱，表明学习停留在表面，缺乏对核心概念的深入理解与灵活运用。  \n**建议**：聚焦1-2个学科核心专题，精读教材并追问“为什么”；增加变式练习与错题溯源，训练知识联结；适度减少刷题量，强化总结反思。', '2026-05-17 01:46:07');
INSERT INTO `sp_student_ability` VALUES (1778953589522, 3, 100, 0, 95, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度严重不足（0分），知识迁移能力较弱（30分）。建议：减少刷题量，转向对核心概念的深度追问与错题归因；尝试用费曼学习法讲解复杂问题，强化知识联结。同时保持活跃度与韧性优势，避免浅层学习陷阱。', '2026-05-17 01:46:30');
INSERT INTO `sp_student_ability` VALUES (1778953840658, 3, 94, 0, 90, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度为零，知识迁移能力显著偏低（30分）。建议：暂停刷题，回归基础概念，精读教材并做变式训练；同时加强“一题多解”与“多题归一”练习，提升关联思维，避免浅层学习。', '2026-05-17 01:50:41');
INSERT INTO `sp_student_ability` VALUES (1778953873313, 3, 94, 0, 90, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度和迁移能力明显薄弱（分别为0和30），说明学习停留于表面，未深入理解原理。建议加强概念追问与变式训练，每学完一类题型后主动归纳规律、举一反三。同时保持活跃度与韧性优势，通过错题反思提升深度。', '2026-05-17 01:51:13');
INSERT INTO `sp_student_ability` VALUES (1778953917173, 3, 94, 0, 90, 80, 30, 80, '根据六维数据，该生知识广度与解题能力突出，但知识深度为0且迁移能力仅30，表明学习停留在表面，缺乏深入理解和灵活应用。建议：减少刷题量，每道题后追问“为什么”，并尝试归纳题型规律；每周用思维导图梳理知识关联，强化深度与迁移。同时保持活跃度和韧性优势。', '2026-05-17 01:51:57');
INSERT INTO `sp_student_ability` VALUES (1778953924551, 3, 94, 0, 90, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度为零，迁移能力较弱。建议加强概念原理的深度理解，多进行变式训练与跨题型归纳，将零散知识结构化，提升灵活应用能力。同时保持学习韧性与活跃度优势。', '2026-05-17 01:52:05');
INSERT INTO `sp_student_ability` VALUES (1778953945480, 3, 94, 0, 90, 80, 30, 80, '该生知识广度与解题能力突出，但知识深度为零，知识迁移能力较弱，表明学习停留于表面，缺乏深入理解与灵活运用。建议：加强概念本质的追问，多做变式训练，将新旧知识关联，提升迁移能力。同时保持活跃度与韧性，逐步攻克难点。', '2026-05-17 01:52:25');
INSERT INTO `sp_student_ability` VALUES (1778954049178, 3, 88, 0, 86, 80, 30, 80, '该生知识面广、解题能力较好，但知识深度为零，且迁移能力显著薄弱。建议：暂停刷题，聚焦一两个核心概念进行深度追问（如“为什么”），并通过跨章节综合题训练知识串联。同时加强错题归因，提升灵活应用能力。', '2026-05-17 01:54:09');
INSERT INTO `sp_student_ability` VALUES (1778954295872, 3, 88, 93, 86, 100, 65, 95, '该生学习韧性与活跃度突出（95/100），知识深度扎实（93），但知识迁移能力显著偏弱（65）。建议：加强跨题型、跨章节的变式训练，主动归纳解题原理而非死记步骤；可尝试“一题多解”与“错题改编”，将孤立知识点串联成网，以提升灵活应用能力。', '2026-05-17 01:58:16');
INSERT INTO `sp_student_ability` VALUES (1778954301488, 3, 88, 93, 86, 100, 65, 95, '该生学习韧性极强，活跃度满分，但知识迁移能力显著偏低（65），存在“学得深但用不活”的问题。建议：增加跨学科综合题训练，主动将新知识联系旧情境；减少刷题量，每道题后反思“能否变式”，强化举一反三。', '2026-05-17 01:58:21');
INSERT INTO `sp_student_ability` VALUES (1778955336573, 3, 88, 93, 86, 100, 65, 95, '该生学习韧性极强，活跃度高，知识深度扎实。但知识迁移能力明显偏弱（65分），解题能力也需提升。建议在巩固深度的同时，加强跨章节、跨学科的联系训练，多做变式题和综合应用题，将扎实的基础转化为灵活的解题能力。', '2026-05-17 02:15:37');
INSERT INTO `sp_student_ability` VALUES (1778955455760, 3, 88, 93, 86, 100, 65, 95, '该生学习韧性和活跃度极强，知识深度扎实，但知识迁移能力显著薄弱（65分）。建议：增加跨学科综合题型训练，主动将新旧知识关联；减少机械刷题，多进行“一题多解”和“举一反三”的复盘，以提升灵活应用能力。', '2026-05-17 02:17:36');
INSERT INTO `sp_student_ability` VALUES (1778955472487, 3, 88, 93, 86, 100, 65, 95, '该生学习韧性极强，活跃度高，知识深度扎实。但知识迁移能力（65）显著薄弱，需加强跨题型、跨章节的综合应用训练。建议精讲精练后增加变式题与开放性问题，并引导总结解题模型，将“会做”转化为“会想”。', '2026-05-17 02:17:52');
INSERT INTO `sp_student_ability` VALUES (1778955474049, 3, 88, 93, 86, 100, 65, 95, '该生学习韧性极强，活跃度满分，知识深度扎实。但知识迁移能力（65）显著偏低，导致“学得深却用不活”。建议减少刷题量，增加跨章节、跨学科的变式训练，重点练习如何将已有知识应用于新情境，以突破瓶颈。', '2026-05-17 02:17:54');
INSERT INTO `sp_student_ability` VALUES (1778955526992, 3, 88, 93, 86, 100, 65, 95, '**诊断**：学习活跃度与韧性极佳，知识深度突出；但知识迁移能力较弱（65），解题能力相对偏低，存在“学得深却用不活”的问题。  \n**建议**：增加跨题型、跨章节综合训练，刻意练习“一题多解”与知识联结，将深度知识转化为灵活解题力。', '2026-05-17 02:18:47');
INSERT INTO `sp_student_ability` VALUES (1778955596608, 3, 17, 0, 20, 80, 20, 50, '根据六维数据，该生解题能力与学习活跃度突出，但知识深度为0，知识迁移和韧性中等。建议：强化深度理解，针对薄弱知识点进行专题突破；通过错题反思促进知识迁移；保持活跃度的同时，增加持久专注练习，提升学习韧性。', '2026-05-17 02:19:57');
INSERT INTO `sp_student_ability` VALUES (1778955605646, 3, 17, 0, 100, 80, 100, 50, '根据您的数据，您在解题能力和知识迁移上表现卓越，但知识深度为0，基础不够扎实。建议在追求解题速度的同时，花时间深入理解核心概念和原理，避免“会做但说不清”。同时提升学习韧性，面对难题时坚持复盘，以巩固长期学习效果。', '2026-05-17 02:20:06');
INSERT INTO `sp_student_ability` VALUES (1778955718147, 3, 25, 0, 100, 80, 100, 50, '该生解题能力与知识迁移突出，但知识深度为零，基础薄弱。建议回归教材，强化概念理解与原理推导，避免只刷题。学习韧性中等，需建立错题本并定期复盘，以平衡广度与深度，提升综合素养。', '2026-05-17 02:21:58');
INSERT INTO `sp_student_ability` VALUES (1778955746378, 3, 25, 0, 100, 80, 100, 50, '根据六维能力数据，该生解题能力与知识迁移极强（均100），但知识深度为零，广度偏低（25），学习韧性中等（50）。建议：强化知识体系构建，通过专题阅读和深度提问补足知识深度；同时利用高迁移能力将解题经验系统化，并设定长期目标提升韧性，避免浅层学习。', '2026-05-17 02:22:26');
INSERT INTO `sp_student_ability` VALUES (1778955807965, 3, 25, 0, 100, 80, 95, 50, '根据六维数据，你的解题能力、知识迁移和学习活跃度非常突出，但知识深度为0且韧性中等。建议：优先补足知识深度，对错题进行归类深挖，避免“只刷不究”；同时设定阶段性小目标，提升学习韧性，以应对高难度挑战。', '2026-05-17 02:23:28');
INSERT INTO `sp_student_ability` VALUES (1778956208181, 3, 25, 0, 100, 80, 95, 50, '根据六维数据，该生解题能力、知识迁移和学习活跃度极强，但知识深度为0、知识广度较低，学习韧性中等。建议：重点加强基础知识的系统梳理与深度理解，避免“会做题但不懂原理”。可尝试错题归因训练，并设定小目标提升韧性，实现从“解题高手”到“真学霸”的跨越。', '2026-05-17 02:30:08');
INSERT INTO `sp_student_ability` VALUES (1778956329272, 3, 25, 0, 100, 80, 95, 50, '根据数据，该生解题能力、知识迁移和学习活跃度突出，但知识深度为零、知识广度偏低，学习韧性中等。建议：加强基础概念的系统梳理，避免只重刷题；每周设定专题深度学习，尝试讲解或归纳核心逻辑；同时培养面对难题的持久钻研习惯，提升抗挫折能力。', '2026-05-17 02:32:09');
INSERT INTO `sp_student_ability` VALUES (1778956408248, 3, 25, 0, 100, 80, 95, 50, '根据数据，你解题能力极强（100分），知识迁移能力突出（95分），但知识深度为0，学习韧性中等（50分）。建议：在刷题基础上，主动探究题目背后的原理与逻辑，填补深度空白；同时设定挑战性目标，培养面对难题时的坚持力，避免止步于熟练度。', '2026-05-17 02:33:28');
INSERT INTO `sp_student_ability` VALUES (1778956427669, 3, 25, 0, 100, 80, 95, 50, '根据六维能力数据，该生解题能力极强（100），知识迁移能力突出（95），但知识深度为0，知识广度仅25，学习韧性中等（50）。建议：加强基础知识的系统梳理，拓展知识面，避免“只刷题不深究”；同时注重错题反思与概念理解，提升深度与韧性，防止高分低能。', '2026-05-17 02:33:48');
INSERT INTO `sp_student_ability` VALUES (1778956467715, 3, 25, 0, 100, 80, 95, 50, '根据你的六维数据，知识迁移（95）和解题能力（100）极强，但知识深度（0）明显不足。建议加强专题深度学习，避免只刷题不深究原理；同时提升学习韧性（50），克服畏难情绪。总体发展不均衡，需补足短板以实现质的飞跃。', '2026-05-17 02:34:28');
INSERT INTO `sp_student_ability` VALUES (1778956473828, 3, 25, 0, 100, 80, 95, 50, '该生解题能力突出，知识迁移能力强，学习活跃，但知识广度与深度不足，韧性中等。建议：适当拓展跨学科阅读以提升广度，并针对薄弱点进行深度探究；同时设定阶段性小目标，培养面对难题的持续钻研习惯，以平衡能力结构。', '2026-05-17 02:34:34');
INSERT INTO `sp_student_ability` VALUES (1778956500201, 2055687643366133761, 0, 0, 20, 0, 20, 50, '该生解题能力和知识迁移尚可，但知识广度、深度及学习活跃度均为零，表明知识体系薄弱且被动。建议立即夯实基础概念，主动拓展阅读和练习。同时，学习韧性较强（50），可善用此优势制定每日学习计划，逐步提升活跃度与知识积累。', '2026-05-17 02:35:00');
INSERT INTO `sp_student_ability` VALUES (1778956609346, 2055687643366133761, 0, 0, 20, 0, 20, 50, '该学生当前能力分布不均：解题能力与知识迁移尚可，但知识广度、深度及活跃度为零，学习韧性较高。建议：利用韧性优势，从基础概念入手，系统补全知识体系；主动参与讨论或练习，提升活跃度；尝试将已会解题方法迁移至新情境，逐步拓展深度与广度。', '2026-05-17 02:36:49');
INSERT INTO `sp_student_ability` VALUES (1778956622736, 3, 25, 0, 100, 80, 95, 50, '根据数据，你解题能力和知识迁移突出，但知识深度为零且广度偏低，学习韧性中等。建议：在刷题外，每道题后追问“为什么用此法”，并每周系统整理错题背后的概念网络。同时设定小目标（如每日攻克一个薄弱知识点），以增强韧性。', '2026-05-17 02:37:03');
INSERT INTO `sp_student_ability` VALUES (1778957156111, 3, 25, 0, 100, 80, 95, 50, '根据数据，该生解题能力极强（100），知识迁移能力高（95），但知识深度为零（0），知识广度偏低（25），学习韧性中等（50）。建议：在保持解题优势的同时，系统拓展知识面，深入理解核心概念背后的原理，避免“只知解题、不懂本质”。同时加强抗挫训练，提升面对复杂问题时的持久钻研能力。', '2026-05-17 02:45:56');
INSERT INTO `sp_student_ability` VALUES (1778957201291, 3, 25, 0, 100, 80, 95, 50, '根据你的六维能力数据，知识迁移和解题能力极强（95/100），但知识深度为0，存在“会解题但未理解本质”的风险。建议加强概念溯源，每道题追问“为什么这样解”，并尝试一题多解。同时学习韧性中等（50），可设置小目标并记录进步，以维持长期学习动力。', '2026-05-17 02:46:41');
INSERT INTO `sp_student_ability` VALUES (1778957206268, 3, 25, 0, 100, 80, 95, 50, '根据数据，该生解题能力与知识迁移极强（100/95），但知识深度为零，学习韧性中等（50）。建议：在刷题基础上，每周针对错题深入追问“为什么”，并尝试一题多解以补足深度。同时设定小目标（如连续专注25分钟）提升韧性，避免因能力断层影响长期学习效果。', '2026-05-17 02:46:46');
INSERT INTO `sp_student_ability` VALUES (1778988885652, 3, 25, 0, 100, 80, 95, 50, '该生解题能力极强（100），知识迁移突出（95），但知识深度为0，知识广度偏低（25），存在“刷题高手、基础薄弱”的隐患。建议：暂停盲目刷题，回归课本补全概念网络，每道题追问“为什么”；同时加强错题反思，提升学习韧性（50）以应对深度探究的挫折感。', '2026-05-17 11:34:46');
